import { StudiumError } from './errors.ts';

/**
 * Feature flags, compiled into every build (app, MCP server, core).
 *
 * `ENABLE_AI_FEATURES` — features that send lesson text to an AI model or serve AI assistants:
 * - quizzes generated by an OpenAI-compatible provider with the student's key (`llm.ts`, mobile "Quiz con l'IA");
 * - the MCP server for AI assistants (`studium-mcp serve`).
 * Temporarily disabled. The code stays in the repository and under test, so turning the flag back on is a
 * one-line change. The local quiz engine (`quiz.ts`) is deterministic and offline: it is not affected.
 *
 * Typed as `boolean` (not the literal `false`) so the type checker keeps checking the code behind the flag.
 */
export const ENABLE_AI_FEATURES: boolean = false;

export class FeatureDisabledError extends StudiumError {
  constructor(feature: string) {
    super(`${feature} is temporarily disabled in this version.`, 'FEATURE_DISABLED');
  }
}

/** Throws when AI features are off: call it at the entry point of every AI code path. */
export function assertAiEnabled(feature = 'AI features'): void {
  if (!ENABLE_AI_FEATURES) throw new FeatureDisabledError(feature);
}
